        contract = {"name": "query", "operation": "playlist_query", "inputs": ["x"], "output": "o"}
        payload = {"criteria": {"filters": [], "limit": 1}}
        r = transform([payload], contract)
        self.assertEqual(r["result"]["sql"], "SELECT id FROM playlists ORDER BY id LIMIT ?")
        self.assertEqual(r["result"]["params"], [1])

