    track_map = {}
    for t in tracks:
        if not isinstance(t, dict):
            raise ValueError("track must be object")
        tid = t.get("id")
        if not isinstance(tid, str):
            raise ValueError("track id must be str")
        if tid in track_map:
            raise ValueError("duplicate track id")
        title = t.get("title")
        artist = t.get("artist")
        path = t.get("path")
        duration = t.get("duration")
